def backfill_vendor_performance_contract(apps, _schema_editor):
    template_model = apps.get_model("gsshop_purchase", "VendorPerformanceTemplate")
    template_line_model = apps.get_model("gsshop_purchase", "VendorPerformanceTemplateLine")
    evaluation_model = apps.get_model("gsshop_purchase", "VendorPerformanceEvaluation")
    evaluation_line_model = apps.get_model("gsshop_purchase", "VendorPerformanceEvaluationLine")
    vendor_model = apps.get_model("gsshop_purchase", "VendorProfile")
    user_model = apps.get_model(*settings.AUTH_USER_MODEL.split("."))

    template_lines = []
    for template in template_model.objects.all().iterator(chunk_size=500):
        template_lines.extend(
            [
                template_line_model(
                    template_id=template.pk,
                    sequence=10,
                    parameter_name="Quality",
                    weight=template.quality_weight,
                    maximum_score=Decimal("100"),
                ),
                template_line_model(
                    template_id=template.pk,
                    sequence=20,
                    parameter_name="Delivery",
                    weight=template.delivery_weight,
                    maximum_score=Decimal("100"),
                ),
                template_line_model(
                    template_id=template.pk,
                    sequence=30,
                    parameter_name="Service",
                    weight=template.service_weight,
                    maximum_score=Decimal("100"),
                ),
            ]
        )
    template_line_model.objects.bulk_create(template_lines, batch_size=500)

    evaluations = list(evaluation_model.objects.all().iterator(chunk_size=500))
    if not evaluations:
        return
    default_user_id = user_model.objects.order_by("pk").values_list("pk", flat=True).first()
    if default_user_id is None:
        raise RuntimeError("A user is required to migrate existing Vendor Performance Evaluations.")
    vendor_company_by_id = dict(
        vendor_model.objects.filter(pk__in={row.vendor_id for row in evaluations}).values_list("pk", "company_id")
    )
    status_map = {
        "submitted": "waiting_approval",
        "approved": "confirmed",
        "cancelled": "rejected",
    }
    assessment_map = {
        "very_poor": "Very_Poor",
        "poor": "Poor",
        "fair": "Fair",
        "good": "Good",
        "excellent": "Excellent",
    }
    evaluation_lines = []
    for evaluation in evaluations:
        evaluation.company_id = vendor_company_by_id[evaluation.vendor_id]
        evaluation.evaluator_id = default_user_id
        evaluation.number = f"VPE-LEGACY-{evaluation.pk:08d}"
        evaluation.status = status_map.get(evaluation.status, evaluation.status)
        evaluation.qualitative_score = (evaluation.overall_score / Decimal("20")).quantize(Decimal("0.01"))
        assessment = assessment_map.get(evaluation.rating, "Fair")
        evaluation_lines.extend(
            [
                evaluation_line_model(
                    evaluation_id=evaluation.pk,
                    sequence=10,
                    parameter_name="Quality",
                    weight=Decimal("40"),
                    maximum_score=Decimal("100"),
                    assessment=assessment,
                    score=evaluation.quality_score,
                ),
                evaluation_line_model(
                    evaluation_id=evaluation.pk,
                    sequence=20,
                    parameter_name="Delivery",
                    weight=Decimal("30"),
                    maximum_score=Decimal("100"),
                    assessment=assessment,
                    score=evaluation.delivery_score,
                ),
                evaluation_line_model(
                    evaluation_id=evaluation.pk,
                    sequence=30,
                    parameter_name="Service",
                    weight=Decimal("30"),
                    maximum_score=Decimal("100"),
                    assessment=assessment,
                    score=evaluation.service_score,
                ),
            ]
        )
    evaluation_model.objects.bulk_update(
        evaluations,
        ["company", "evaluator", "number", "status", "qualitative_score"],
        batch_size=500,
    )
    evaluation_line_model.objects.bulk_create(evaluation_lines, batch_size=500)


